import {
  type ChartCommonProps,
  ChartFrame,
  type ChartRange,
  PeriodSelect,
  safeRatio,
  sum,
  useChartRange,
} from "./pro-chart";
export interface HeatmapRow {
  label: string;
  values: number[];
}
export interface HeatmapRange extends ChartRange {
  rows: HeatmapRow[];
  columns?: string[];
  max?: number;
}
export interface HeatmapChartCardProps extends ChartCommonProps {
  rows?: HeatmapRow[];
  columns?: string[];
  ranges?: HeatmapRange[];
  color?: string;
  max?: number;
  /** Opt into keyboard inspection of each cell. */
  focusable?: boolean;
  columnLabelEvery?: number;
}
export const HEATMAP_COLUMNS = Array.from({ length: 12 }, (_, i) => String(i * 2).padStart(2, "0"));
export const HEATMAP_ROWS: HeatmapRow[] = HEATMAP_DEMO_RANGES[0]!.rows;
const RANGES: HeatmapRange[] = HEATMAP_DEMO_RANGES;

export function HeatmapChartCard({
  rows,
  columns = HEATMAP_COLUMNS,
  ranges: supplied,
  color = "var(--color-chart-6)",
  max,
  title = "Active users",
  focusable = false,
  columnLabelEvery = 1,
  ...props
}: HeatmapChartCardProps = {}) {
  const ranges = supplied ?? (rows ? undefined : RANGES),
    period = useChartRange(ranges, props.defaultRange, props.onRangeChange),
    data = period.current?.rows ?? rows ?? HEATMAP_ROWS,
    cols = period.current?.columns ?? columns,
    [active, setActive] = useState<{ row: number; col: number } | null>(null),
    ceiling = period.current?.max ?? max ?? Math.max(0, ...data.flatMap((r) => r.values)),
    cell = active ? data[active.row]?.values[active.col] : undefined;
  const tint = (v: number, inspected = false) =>
    `color-mix(in srgb, ${inspected ? color.replace(/var\(--color-chart-(\d+)\)/, "var(--color-chart-$1-active)") : color} ${Math.round(8 + safeRatio(v, ceiling) * 92)}%, var(--color-chart-track))`;
  return (
    <ChartFrame
      title={active ? `${data[active.row]?.label} · ${cols[active.col] ?? ""}` : title}
      value={
        cell ?? period.current?.headline ?? props.headline ?? sum(data.flatMap((r) => r.values))
      }
      format={props.format}
      delta={active ? undefined : (period.current?.delta ?? props.delta)}
      animateNumber="always"
      pulseKey={`${period.id}:${active?.row ?? "all"}:${active?.col ?? "all"}`}
      className={props.className}
      height={329}
      action={
        <PeriodSelect
          ranges={ranges}
          selected={period.id}
          onChange={(id) => {
            setActive(null);
            period.select(id);
          }}
          label={period.current?.label ?? props.range ?? "Last 7 days"}
        />
      }
    >
      <div
        className="grid min-h-0 flex-1 gap-1"
        style={{
          gridTemplateColumns: `auto repeat(${Math.max(1, cols.length)}, minmax(0,1fr))`,
          gridTemplateRows: `repeat(${Math.max(1, data.length)}, minmax(0,1fr)) auto`,
        }}
      >
        {data.map((row, r) => (
          <Fragment key={row.label}>
            <ChartAxisLabel
              active={active?.row === r}
              className="flex items-center pe-2 whitespace-nowrap"
            >
              {row.label}
            </ChartAxisLabel>
            {cols.map((col, c) => (
              <ChartSwatch
                focusable={focusable}
                key={col}
                aria-label={`${row.label} ${col}: ${row.values[c] ?? 0}`}
                onInspect={(inspected) => setActive(inspected ? { row: r, col: c } : null)}
                className={cx(
                  "min-h-0 rounded-[4px] transition-[background-color,box-shadow] duration-150 ease-out",
                  active?.row === r && active?.col === c && "ring-2 ring-chart-cursor",
                )}
                style={{
                  backgroundColor: tint(row.values[c] ?? 0, active?.row === r && active?.col === c),
                }}
              />
            ))}
          </Fragment>
        ))}
        <span />
        {cols.map((col, c) => (
          <ChartAxisLabel
            key={col}
            active={active?.col === c}
            className={cx(
              "truncate pt-0.5 text-center",
              c % Math.max(1, columnLabelEvery) !== 0 && "invisible",
            )}
          >
            {col}
          </ChartAxisLabel>
        ))}
      </div>
      <div className="flex w-full items-center justify-end gap-1.5 pb-1 text-caption-1-medium text-text-tertiary">
        <span>Less</span>
        {[0, 0.25, 0.5, 0.75, 1].map((v) => (
          <span
            key={v}
            className="size-3 rounded-[3px]"
            style={{ background: tint(v * ceiling) }}
          />
        ))}
        <span>More</span>
      </div>
    </ChartFrame>
  );
}

